schema_ddl:
CREATE TABLE cnt (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_conto VARCHAR(50) NOT NULL UNIQUE,
    descrizione TEXT NOT NULL,
    tipo_conto VARCHAR(20) NOT NULL CHECK (tipo_conto IN ('attivo', 'passivo', 'costo', 'ricavo', 'patrimonio'))
);

CREATE TABLE reg (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    data_registrazione DATE NOT NULL DEFAULT CURRENT_DATE,
    descrizione_registrazione TEXT NOT NULL
);

CREATE TABLE mov (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reg_id INT NOT NULL REFERENCES reg(id) ON DELETE CASCADE,
    cnt_id INT NOT NULL REFERENCES cnt(id),
    imp NUMERIC(12, 2) NOT NULL CHECK (imp >= 0),
    segno VARCHAR(1) NOT NULL CHECK (segno IN ('D', 'A'))
);

CREATE TABLE doc (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reg_id INT NOT NULL REFERENCES reg(id) ON DELETE CASCADE,
    numero_documento VARCHAR(50) NOT NULL,
    data_documento DATE NOT NULL
);

CREATE TABLE aux (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cnt_id INT NOT NULL REFERENCES cnt(id),
    note_ausiliarie TEXT,
    valore_riferimento NUMERIC(12, 2) DEFAULT 0.00
);
